methods=[]
for node in p['counter']['nodes']:
 id=node['id']; group,name=id.split('.',1); purpose,cost,opt,inv,risk,priority=rows[id]
 sourcepath=paths.get(group); source=None
 if sourcepath:
  ls=texts[sourcepath]
  defs=[(i+1,s.strip()) for i,s in enumerate(ls) if re.match(r'^\s+(?:private |public |protected |async )*'+re.escape(name)+r'\(',s)]
  if defs:source={'path':sourcepath,'line':defs[0][0]}
 refs=[]
 pattern=re.compile(r'\.'+re.escape(name)+r'\s*\(')
 for f,ls in texts.items():
  for i,s in enumerate(ls):
   if pattern.search(s):refs.append({'path':f,'line':i+1,'caller':s.strip()[:240],'kind':'static-reference'})
 status='no-change' if 'не требуется' in opt or 'не обоснован' in opt else 'proposal'
 validation='CPU negative control + exact field/material/PNG parity live/replay/undo/redo; свежие/pooled ресурсы, несколько цветов/слоёв, crossing tile seam, context loss. Затем A/B на реальном устройстве с GPU trace и одинаковым журналом; отдельно latency и natural completion.'
 methods.append({'id':id,'summary':purpose,'complexity':cost,'priority':priority,'status':status,'metrics':node,'source':source,'callsites':refs,'observedCallers':[e for e in p['counter']['edges'] if e['target']==id],'proposals':[{'title':opt,'rationale':cost,'qualityInvariant':inv,'validation':validation,'risk':risk}], 'speedup':'Не измерено; ускорение не обещается до A/B.','reviewBasis':'Исходник6aa14a43, измеренный сценарий, статические ссылки; не доказательство полной эквивалентности.'})
out={'schemaVersion':1,'source':'6aa14a43','scope':'36 instrumented methods in one Surface round400 scenario','limitations':['Inclusive total нельзя суммировать. Self исключает только instrumented children.','CPU GL submission не измеряет GPU duration.','static-reference может относиться к иному receiver с тем же именем; это не доказанный runtime caller. ObservedCallers — ближайший instrumented caller, не обязательно прямой.','Все proposals — гипотезы, ни одна здесь не реализована/не validated.','Отмена вычислений ради приближённого результата, уменьшение field/resolution/iterations и decimation не считаются оптимизацией без потерь.'],'methods':methods}
pathlib.Path('docs/qa/callgraph-viewer/method-audit.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
md=['# Аудит36 измеренных методов акварели','', 'Версия`6aa14a43`. Предложения не реализованы и не прошли аппаратную проверку. «Без потерь» ниже — требуемый инвариант, а не уже доказанное свойство патча.','',*['- '+x for x in out['limitations']],'','ПриоритетP1 означает начать проверку здесь, а не доказанное ускорение. В первую очередь: повторные clear, same-size copyTo без storage redefine, reuse geometry/flow и dirty composite. Выборочное scissor поля, уменьшение итераций и перестановка контактов отвергнуты как неэквивалентные без отдельного доказательства.','']
for m in methods:
 md+=['## '+m['id'], '',f"{m['priority']} · {m['status']} · вызовов{m['metrics']['calls']}; total{m['metrics']['totalMs']:.2f}ms; self{m['metrics']['selfMs']:.2f}ms; max{m['metrics']['maxMs']:.2f}ms.",'',m['summary']+' '+m['complexity'],'', '**Предложение.** '+m['proposals'][0]['title'],'','**Инвариант.** '+m['proposals'][0]['qualityInvariant'],'','**Риск.** '+m['proposals'][0]['risk'],'','**Проверка.** '+m['proposals'][0]['validation'],'']
 if m['source']:md+=['Определение: `'+m['source']['path']+':'+str(m['source']['line'])+'`.','']
 md+=['Наблюдаемые ближайшие instrumented callers: '+', '.join(e['source']+' ×'+str(e['calls']) for e in m['observedCallers'])+'.','',f"Статических ссылок: {len(m['callsites'])}; полный перечень с точными строками6aa14a43 — в JSON. Разрешение динамического receiver отдельно не доказано.",'']
